SEP = ","
ESC = "\\"


def _escape(part):
    """对 part 内的分隔符与转义符做转义，保证拼接后无歧义。"""
    s = str(part)
    return s.replace(ESC, ESC + ESC).replace(SEP, ESC + SEP)


def make_key(namespace, *parts):
    """构造缓存键：namespace 前缀 + 各 part 转义后用 SEP 连接。"""
    return namespace + "|" + SEP.join(_escape(p) for p in parts)

