from clock import floor_hour


def bucket_of(ts, start):
    """返回 ts 相对 start 落在第几个 60 分钟桶（0-based）。

    窗口从 start 这一刻起算，而不是从整点起算。
    """
    delta = (ts - start).total_seconds()
    return int(delta // 3600)


def aggregate(events, start, hours, key="value"):
    """按小时聚合事件值，返回长度 hours 的列表。"""
    out = [0] * hours
    for e in events:
        i = bucket_of(e["ts"], start)
        if 0 <= i < hours:
            out[i] += e[key]
    return out

