class Registry:
    """监听器注册表。"""

    def __init__(self):
        self._by_topic = {}

    def add(self, topic, fn):
        """注册监听器；同一 (topic, fn) 幂等，重复注册不会新增。"""
        bucket = self._by_topic.setdefault(topic, [])
        if fn not in bucket:
            bucket.append(fn)
        return len(bucket)

    def get(self, topic):
        return list(self._by_topic.get(topic, []))

    def topics(self):
        return sorted(self._by_topic)

from registry import Registry

_bus = Registry()
_dispatch_count = {}


def subscribe(topic, fn):
    """订阅主题。同一 (topic, fn) 重复订阅幂等。"""
    return _bus.add(topic, fn)


def publish(topic, payload):
    for fn in _bus.get(topic):
        fn(payload)
    _dispatch_count[topic] = _dispatch_count.get(topic, 0) + 1
    return len(_bus.get(topic))


def counts():
    return dict(_dispatch_count)

