class UserDao:
    def __init__(self, store):
        self.store = store
        self.writes = 0
        self._undo = []

    def put(self, key, value):
        if value.get("blocked"):
            raise ValueError("blocked user")
        # 记录本次写入，便于批量失败时撤销
        self._undo.append((key, self.store.get(key)))
        self.store[key] = value
        self.writes += 1
        return key

    def undo_all(self):
        """按写入的逆序撤销本次批量的所有写入。"""
        for key, prev in reversed(self._undo):
            if prev is None:
                self.store.pop(key, None)
            else:
                self.store[key] = prev
        n = len(self._undo)
        self._undo = []
        return n

