from graph import Node


def to_dict(node, seen=None, path=None):
    """把节点树序列化成 dict。

    seen 记录**当前递归路径**上的节点：只有真正的环才折叠为引用，
    被多个父节点共享（但不在同一条路径上）的子节点应当正常展开。
    """
    seen = set() if seen is None else seen
    if node.nid in seen:
        return {"id": node.nid, "ref": True}
    nxt = seen | {node.nid}
    return {"id": node.nid, "children": [to_dict(c, nxt) for c in node.children]}


def dumps(node):
    return to_dict(node)
